import sys

MINOR = {"a", "an", "and", "as", "at", "but", "by", "for", "in", "nor", "of", "on", "or", "the", "to"}


def headline(line):
    words = line.split()
    out = []
    for word in words:
        stripped_word = word.strip(',.!?;')
        if stripped_word.lower() in MINOR:
            if out and out[-1] != word:
                out.append(word.lower())
        else:
            title_word = stripped_word.title()
            if out:
                out.append(title_word)
            else:
                out.insert(0, title_word)
    return " ".join(out)


def main():
    for line in sys.stdin:
        print(headline(line))


if __name__ == "__main__":
    main()
